1	{
2	  "$schema": "https://json-schema.org/draft-07/schema#",
3	  "$id": "https://harness.local/system-spec-harness/completeness-findings.schema.json",
4	  "title": "system-spec completeness evaluation report (C05)",
5	  "description": "生成された仕様書ドキュメントセットの完成度評価レポート。上位概念・意思決定・網羅性・deep knowledge・鮮度・prompt品質の観点 + 総合判定をfail-closedに再導出し、独立auditor帰属を実fork証跡へ接地させる。",
6	  "type": "object",
7	  "additionalProperties": false,
8	  "required": ["evaluator", "verdict", "artifact_snapshot", "aspects", "audit_delegations", "findings", "gaps"],
9	  "properties": {
10	    "evaluator": {
11	      "type": "object",
12	      "additionalProperties": false,
13	      "required": ["name", "version", "context"],
14	      "properties": {
15	        "name": {"const": "assign-system-spec-completeness-evaluator"},
16	        "version": {"type": "string", "minLength": 1},
17	        "context": {"const": "fork"}
18	      }
19	    },
20	    "spec_dir": {"type": "string", "description": "評価した仕様書ディレクトリ。引数 spec_dir に渡された値をそのまま書き、説明や注記を混ぜない。呼び出し側はこの値が自分の渡した dir に解決するかを照合する (aggregate-completeness.py --report <report> --spec-dir <spec_dir>)。"},
21	    "verdict": {"type": "string", "enum": ["PASS", "FAIL"]},
22	    "artifact_snapshot": {
23	      "type": "object",
24	      "description": "評価開始時点の全入力を固定するスナップショット。receipt writer は現在値との完全一致を要求し、評価後の追加・変更・削除を fail-closed で拒否する。",
25	      "additionalProperties": false,
26	      "required": ["schema_version", "artifacts"],
27	      "properties": {
28	        "schema_version": {"const": "system-spec-artifact-snapshot/v1"},
29	        "artifacts": {
30	          "type": "object",
31	          "minProperties": 1,
32	          "additionalProperties": {"type": "string", "pattern": "^[0-9a-f]{64}$"}
33	        }
34	      }
35	    },
36	    "aspects": {
37	      "type": "object",
38	      "additionalProperties": false,
39	      "required": ["foundation_trace", "decision_guidance", "matrix_coverage", "design_knowledge_reflection", "doc_freshness", "prompt_quality"],
40	      "properties": {
41	        "foundation_trace": {"$ref": "#/definitions/aspect"},
42	        "decision_guidance": {"$ref": "#/definitions/aspect"},
43	        "matrix_coverage": {"$ref": "#/definitions/aspect"},
44	        "design_knowledge_reflection": {"$ref": "#/definitions/aspect"},
45	        "doc_freshness": {"$ref": "#/definitions/aspect"},
46	        "prompt_quality": {"$ref": "#/definitions/aspect"}
47	      }
48	    },
49	    "audit_delegations": {
50	      "type": "array",
51	      "description": "独立 context (現行 Agent fork、legacy Task 互換) で起動した監査 sub-agent の receipt 一覧。auditor が C05 自身でない観点 (primary) と、宣言された sub-input 監査 (matrix_coverage の C06) に 1 件ずつ必須。PostToolUse hook が書く fork 台帳の session・tool・response digest・verdict と突合され、裏取りできない帰属または判定は fail-closed で violation になる。",
52	      "items": {"$ref": "#/definitions/audit_delegation"}
53	    },
54	    "gate_results": {
55	      "type": "array",
56	      "items": {"$ref": "#/definitions/gate_result"}
57	    },
58	    "findings": {
59	      "type": "array",
60	      "minItems": 1,
61	      "items": {"$ref": "#/definitions/finding"}
62	    },
63	    "gaps": {
64	      "type": "array",
65	      "items": {"type": "string", "minLength": 1},
66	      "description": "不足事項一覧。verdict=FAIL のとき非空 (elicit/doc-fetch/compile への差し戻し材料)。"
67	    }
68	  },
69	  "definitions": {
70	    "aspect": {
71	      "type": "object",
72	      "additionalProperties": false,
73	      "required": ["verdict", "auditor", "component", "summary"],
74	      "properties": {
75	        "verdict": {"type": "string", "enum": ["PASS", "FAIL", "INDETERMINATE"]},
76	        "score": {"type": "number", "minimum": 0, "maximum": 100},
77	        "auditor": {"type": "string", "minLength": 1},
78	        "component": {"type": "string", "minLength": 1},
79	        "summary": {"type": "string", "minLength": 1},
80	        "evidence": {"type": "array", "items": {"type": "string"}}
81	      }
82	    },
83	    "audit_delegation": {
84	      "type": "object",
85	      "additionalProperties": false,
86	      "required": ["aspect", "role", "auditor", "component", "dispatch", "verdict", "evidence"],
87	      "properties": {
88	        "aspect": {"type": "string", "enum": ["foundation_trace", "decision_guidance", "matrix_coverage", "design_knowledge_reflection", "doc_freshness", "prompt_quality"]},
89	        "role": {"type": "string", "enum": ["primary", "sub_input"], "description": "primary=当該観点の一次根拠 / sub_input=補助根拠 (独立観点へ昇格させない)"},
90	        "auditor": {"type": "string", "minLength": 1, "description": "plugin 同梱の agent 定義 (agents/<auditor>.md) に実在する名前"},
91	        "component": {"type": "string", "minLength": 1},
92	        "dispatch": {
93	          "type": "object",
94	          "additionalProperties": false,
95	          "required": ["tool", "subagent_type", "session_id", "response_sha256"],
96	          "properties": {
97	            "tool": {"enum": ["Task", "Agent"], "description": "subagent 起動ツール名の観測値 (旧ハーネス/Codex 系='Task', 現行 Claude Code='Agent')。aggregate-completeness.py の LEDGER_TOOL_NAMES と整合"},
98	            "tool_use_id": {"type": "string", "minLength": 1, "description": "schema 1.2 fork 台帳の dispatch 識別子。同一 session 内の PostToolUse 観測値と一致必須。旧 Task の schema 1.1 receipt 互換を維持するため schema 上は optional だが、現行 Agent または1.2行へ接地する receiptで欠落した場合は集約器がfail-closedで拒否する"},
99	            "subagent_type": {"type": "string", "minLength": 1, "description": "auditor と一致すること。fork 台帳の subagent_type と突合される"},
100	            "session_id": {"type": "string", "minLength": 1, "description": "fork を起動した評価 session の id。宣言単独では自己申告のため、fork 台帳 (hook が harness 観測値を記録) に同一 (session_id, subagent_type) の行が実在するときだけ裏取り成立。必須 receipt 全件で同一 session を名指しすること (単一 run 収束)"},
101	            "response_sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$", "description": "PostToolUse hook が観測した監査 response の canonical sha256。台帳に同一 session・subagent・tool・digest の行があり、そこに記録された audit_verdict が receipt.verdict と一致するときだけ帰属と判定の裏取りが成立する"}
102	          }
103	        },
104	        "verdict": {"type": "string", "enum": ["PASS", "FAIL", "INDETERMINATE"], "description": "role=primary のとき aspects[aspect].verdict と一致必須 (監査判定の忠実転記)"},
105	        "evidence": {"type": "array", "minItems": 1, "items": {"type": "string", "minLength": 1}}
106	      }
107	    },
108	    "gate_result": {
109	      "type": "object",
110	      "additionalProperties": false,
111	      "required": ["id", "name", "exit_code"],
112	      "properties": {
113	        "id": {"type": "string", "minLength": 1},
114	        "name": {"type": "string", "minLength": 1},
115	        "conditions": {"type": "array", "items": {"type": "string"}},
116	        "command": {"type": "array", "items": {"type": "string"}},
117	        "exit_code": {"type": "integer"},
118	        "stdout": {"type": "string"},
119	        "stderr": {"type": "string"},
120	        "subgates": {
121	          "type": "array",
122	          "minItems": 4,
123	          "maxItems": 4,
124	          "items": [
125	            {"allOf": [{"$ref": "#/definitions/knowledge_subgate"}, {"properties": {"profile": {"const": "knowledge"}}}]},
126	            {"allOf": [{"$ref": "#/definitions/knowledge_subgate"}, {"properties": {"profile": {"const": "doctrine"}}}]},
127	            {"allOf": [{"$ref": "#/definitions/knowledge_subgate"}, {"properties": {"profile": {"const": "required-info"}}}]},
128	            {"allOf": [{"$ref": "#/definitions/knowledge_subgate"}, {"properties": {"profile": {"const": "cross"}}}]}
129	          ],
130	          "additionalItems": false
131	        }
132	      }
133	    },
134	    "knowledge_subgate": {
135	      "type": "object",
136	      "additionalProperties": false,
137	      "required": ["profile", "command", "exit_code", "stderr"],
138	      "properties": {
139	        "profile": {"type": "string", "enum": ["knowledge", "doctrine", "required-info", "cross"]},
140	        "command": {"type": "array", "minItems": 1, "items": {"type": "string"}},
141	        "exit_code": {"type": "integer"},
142	        "stderr": {"type": "string"}
143	      }
144	    },
145	    "finding": {
146	      "type": "object",
147	      "additionalProperties": false,
148	      "required": ["severity", "bucket", "observation"],
149	      "properties": {
150	        "severity": {"type": "string", "enum": ["high", "medium", "low", "info"]},
151	        "bucket": {"type": "string", "minLength": 1},
152	        "observation": {"type": "string", "minLength": 1},
153	        "suggested_fix": {"type": "string"},
154	        "evidence": {"type": "array", "items": {"type": "string"}}
155	      }
156	    }
157	  }
158	}
159
